-- =====================================================================
-- V138 — fix pico:front-gate-create's Flow Variant field: it silently
-- rendered nothing because "optionsSource":{"type":"entity",...} isn't
-- actually supported on this page's Form component (Grid/Section schema,
-- V127/V136) — confirmed by the working precedent one section over:
-- pico:parking-scan's bay_code field uses a plain static "options" array
-- and renders fine. Swap to the same confirmed pattern, listing the 6
-- M10 gate-pass workflows already verified (V136 comment) to share the
-- same DRAFT -> GATE_PASS_CREATED first transition.
-- =====================================================================

UPDATE page_version pv
SET pv.body_json = '{"schemaVersion": "1.0.0", "slug": "pico:front-gate-create", "title": "Front Gate \\u2014 Live Inward / Outward Gatepass Details", "status": "published", "version": 1, "roles": ["FrontGate", "TenantAdmin"], "dataSources": [], "streams": [], "layout": {"type": "Grid", "id": "root", "props": {"columns": 12, "gap": 16}, "children": [{"type": "Section", "id": "sec-intake", "props": {"title": "New Vehicle Intake", "span": 12, "subtitle": "Capture the vehicle at the gate, then Create Gate Pass to start the selected flow."}, "children": [{"type": "Form", "id": "form-intake", "props": {"submitLabel": ""}, "bindings": {"fields": [{"name": "vehicleNo", "label": "Vehicle No", "type": "text", "required": true, "placeholder": "TN 33 P 8452", "helperText": "Enter with spaces, e.g. TN 33 P 8452", "warnWhen": "!#form.vehicleNo.includes('' '')", "warnMessage": "Vehicle number entered without spaces \\u2014 please use format: TN 33 P 8452"}, {"name": "loadingType", "label": "Loading Type", "type": "select", "required": true, "options": ["LOADING", "UN-LOADING", "RETURN STOCK", "EMPTY", "OTHERS"]}, {"name": "vehicleCategory", "label": "Vehicle Category", "type": "select", "required": true, "options": ["BODY VEHICLE", "TANKER", "OPEN BODY", "CRANE", "JCB", "TRACTOR", "STAFF BUS", "CAR", "TWO-WHEELER", "AUTO"]}, {"name": "flowVariant", "label": "Flow Variant", "type": "select", "required": true, "options": ["M10.TankerInbound", "M10.PackUnload", "M10.ReturnStockIn", "M10.TankerOutbound", "M10.PackLoading", "M10.FGLoading"]}]}, "children": [{"type": "WorkflowActionButton", "id": "btn-create", "props": {"label": "Create Gate Pass", "action": "workflow.transition", "workflowCode": "{{form.flowVariant}}", "targetState": "GATE_PASS_CREATED", "trigger": "page.submitted", "color": "primary"}}]}]}, {"type": "Section", "id": "sec-print", "props": {"title": "Gate Pass QR", "span": 12, "subtitle": "Shown after Create Gate Pass succeeds."}, "children": [{"type": "PrintButton", "id": "btn-print", "props": {"printCode": "gate-pass", "idFrom": "lastCreatedId", "label": "Print Gate Pass"}}]}, {"type": "Section", "id": "sec-queue", "props": {"title": "Gate Passes In Progress", "span": 12, "subtitle": "Vehicles you have logged that are moving through parking, weighment and QC."}, "children": [{"type": "WorkflowQueueList", "id": "queue-frontgate", "props": {"persona": "frontgate", "pageSize": 25, "cardFields": ["vehicleNo", "gpNumber", "flowVariant", "currentState"]}}]}]}}'
WHERE pv.page_id = (SELECT id FROM page_definition WHERE code = 'pico:front-gate-create')
  AND pv.status = 'PUBLISHED';
